u32 GameSceneWorld::vfunc_C0(Location const & location)
{
    u32 result = 0;
    GameSceneFarmPlotLocation hit;
    if (TryGetFarmPlotAtLocation(*this, location, hit)) {
        result = hit.plot->method_0800A190(this->save->clock.weather_today == WEATHER_SUNNY);
        if (this->vfunc_14() == location.GetMap()) {
            GameSceneWorldMap * map = this->data.map.value;
            FieldPlotRenderData const * render_data =
                this->save->farm.field.PlotRenderDataAt(hit.column, hit.row);
            RefreshFieldPlotTiles(map, hit.tile_x, hit.tile_y, hit.plot, render_data);
        }
        if (result == 3) {
            for (u32 index = 0; index < ARRAY_COUNT(this->unk_1080); ++index) {
                if (this->unk_1080[index].state == 0) {
                    this->unk_1080[index].state = 2;
                    this->unk_1080[index].tile_x = hit.tile_x;
                    this->unk_1080[index].tile_y = hit.tile_y;
                    break;
                }
            }
        }
    }
    return result;
}

