static inline GameSceneEventIconRecord * GetWorldEventIconRecordData()
{
    return gCurrentGameSceneScriptController->event_icon_records;
}

static inline GameSceneEventIconRecord & GetWorldEventIconRecord(MaryEventIconSlot slot)
{
    return GetWorldEventIconRecordData()[slot];
}

void GameSceneWorld::CreateEventIcon(MaryEventIconSlot slot, MaryMapSpaceX x,
    MaryMapSpaceY y, MaryEventIconLayer layer, u16 icon_id)
{
    GameSceneEventIconRecord & record = GetWorldEventIconRecord(slot);
    record.state = 1;
    record.location.map = static_cast<MaryMapId>(vfunc_14());
    record.location.x = x;
    record.location.y = y;
    record.layer = layer;
    record.icon_id = icon_id;
    event_icon_sprites[slot] = new GameSceneGroupSprite(vfunc_64(), icon_id, this, 2, 0x1B);
}

void GameSceneWorld::RemoveEventIcon(MaryEventIconSlot slot)
{
    GetWorldEventIconRecord(slot).state = 0;
    event_icon_sprites[slot] = nullptr;
}

