bool GameSceneWorld::vfunc_F0(u32 map_id, u32 level)
{
    bool hit = false;
    if (map_id == MAP_FARM) {
        u32 row = 0;
        GameStateSaveImage * const & saveData = save;
        u8 const & power = gUnk_080F0807[level];
        for (; row < Farm::FIELD_HEIGHT; ++row) {
            for (u32 column = 0; column < Farm::FIELD_WIDTH; ++column) {
                u32 effect = saveData->farm.field.PlotAt(column, row).method_0800A33C(power);
                if (effect == 1 || effect == 2)
                    saveData->farm.method_08009B68(1);
                hit |= effect != 0;
            }
        }
    } else {
        i32 season = GetCalendarEffectiveSeason(save->clock.calendar);
        FieldItemState & items = save->field_items;
        for (u32 index = FIELD_ITEM_RECORD_SHARED_BEGIN; index < FIELD_ITEM_RECORD_SHARED_END; ++index) {
            if (items.IsAvailable(index, season)) {
                FieldItemInstance item = items.GetRecord(index);
                if (item.map == map_id) {
                    GameSceneFieldItemToolResult result;
                    func_080174C8(save->farm, save->field_items, index, season,
                        gUnk_080F0807[level], false, result);
                    hit |= !result.rejected;
                }
            }
        }
    }
    if (hit)
        QueueScript(GameSceneScriptRequest(0x3CF, 0), 0);
    return hit;
}

